\pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\lang1033\fs24  1r\endash 81v {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Nicolaus de Dinkelspuhel}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 De tribus punctis poenitentiae}}\plain \f1\b\lang1033\fs24   
\par \pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\i\lang1033\fs24  >De penitencia secundum magistrum Nicolaum< Ecce nunc tempus acceptabile, 2\u176 \'b0 Cor. 6\u176 \'b0 \plain \f1\lang1033\fs24  (2)\plain \f1\i\lang1033\fs24 . Duo sunt tempora hominis, unum iusticie, quod incipit in hominis morte ... \plain \f1\lang1033\fs24  73v \plain \f1\i\lang1033\fs24  >De tempore penitendi< Dicto de tribus partibus penitencie scilicet contricione, confessione et satisfaccione est nunc videndum quod ..., \plain \f1\lang1033\fs24  79v \plain \f1\i\lang1033\fs24  >De sigillo confessionis< Ultimo ad incantandum confessores et ad actrahendum confitentes ... \plain \f1\lang1033\fs24  \emdash  \plain \f1\i\lang1033\fs24 ... contra triplex ius naturale ecclesiasticum et divinum. A quo nos custodiat qui sine fine vivit et regnat Amen. \plain \f1\lang1033\fs24  \emdash  Rest der Seite und 2 folgende Bl. (81a und 81b) leer. 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20  Siehe \plain \f1\scaps\lang1033\fs20 Madre\plain \f1\lang1033\fs20 , 180\endash 186, hier 184 Hs. genannt; \plain \f1\scaps\lang1033\fs20 Schneyer/H\plain \f1\scaps\lang1033\fs20 \u246 \'f6\plain \f1\scaps\lang1033\fs20 dl\plain \f1\lang1033\fs20 , Initien}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

