\pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\lang1033\fs24  178vb\endash 182ra {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Valerius (Ps.)}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Epistola ad Rufinum}}\plain \f1\b\lang1033\fs24   
\par \pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\i\lang1033\fs24  >Incipit epistola Valerii ad Rufinum< Loqui prohibeor et tacere non possum, gruem odi et vocem ulule et aves ceteras ... \plain \f1\lang1033\fs24  \emdash  \plain \f1\i\lang1033\fs24 ... ex quo timeo, sed ne per Orestem scribent vel scripsisse videar. Vale karissime. Explicit epistola Valerii ad Ruffinum. 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20  PL 30, 254\endash 261; ed. \plain \f1\scaps\lang1033\fs20 James\plain \f1\lang1033\fs20 , Oxford 1914. \plain \f1\scaps\lang1033\fs20 Lambert\plain \f1\lang1033\fs20 , BHM, IIIB, Nr.336}

