\pard\fi0\li0\ql\ri0\sb105\sa105\itap0 {\field{\*\fldinst HYPERLINK "hida://5260[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Helles Leder auf Holzdeckeln}}\plain \f1\lang1033\fs20   (15.Jh.). {\field{\*\fldinst HYPERLINK "hida://5300[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Streicheisenlinien}}\plain \f1\lang1033\fs20 , dazwischen florale Einzelstempel. Spuren zweier Schlie\u223 \'dfen und von je f\u252 \'fcnf Buckelbeschl\u228 \'e4gen vorn und hinten. Hinten Ketten\u246 \'f6se. Papierschild (17.Jh.) auf dem Vorderdeckel mit verbla\u223 \'dfter Titelangabe (\plain \f1\i\lang1033\fs20  Speculum clericorum\plain \f1\lang1033\fs20 ) und Reiser-Nummer (\plain \f1\i\lang1033\fs20  p.54 n.16\plain \f1\lang1033\fs20 ). }

