\par \pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\i\lang1033\fs24  Erunt signa in sole et luna et stellis et in terra pressura gencium etc. \plain \f1\lang1033\fs24  (Lc 21,25)\plain \f1\i\lang1033\fs24 . {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Dominus ac redemptor noster perituri mundi mala previdens nobis intimari curavit dicens}}\plain \f1\i\lang1033\fs24  ... \plain \f1\lang1033\fs24  \emdash  \plain \f1\i\lang1033\fs24 ... intraverunt cum eo ad nupcias. Dominus Ihesus Christus dignetur nos sic preparare ut possimus effugere omnia mala ... quod ipse prestare dignetur amen. 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20  M\u252 \'fcnchen, UB, fol. 132, f.104rb}

