\pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\lang1033\fs24  77v\endash 81v {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Sermo de sancta trinitate}}\plain \f1\b\lang1033\fs24   
\par \pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\i\lang1033\fs24  >Sermo de sancta trinitate< Erat homo Nicodemus nomine princeps Iudeorum, Ioh. III \plain \f1\lang1033\fs24  (1)\plain \f1\i\lang1033\fs24 . {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Festum trinitatis ab ecclesia non fiebat, sed quia circa ipsam trinitatem multe hereses subcrescebant}}\plain \f1\i\lang1033\fs24 , ideo Carulus christianissimus imperator rogavit Alchuinum magistrum suum ut historiam de sancta trinitate componeret ... \plain \f1\lang1033\fs24  \emdash  \plain \f1\i\lang1033\fs24 ... et ad parcendum vel miserandum inducit. 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20  Vgl. \plain \f1\i\lang1033\fs20  Festum Sancte trinitatis antiquitus non celebrabatur, sed quia multi hereses fiebant\plain \f1\lang1033\fs20   in: W\u252 \'fcrzburg, UB, 4 an: I.t.f. 66, f.32r\endash 34v. }

