\pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\lang1033\fs24  86r\endash 94v {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Sermones II de praemio beatorum et de poena malorum}}\plain \f1\b\lang1033\fs24   
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  86r\endash 87r \plain \f1\i\lang1033\fs24  >De premio beatorum et pena malorum sermo< Et cum apparuisset sigillum terre, ecce equus pallidus ... mors, Apok. VI \plain \f1\lang1033\fs24  (7\endash 8)\plain \f1\i\lang1033\fs24 . {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Sic audivistis de sponsis dyaboli et quibus hominibus eas despons}}\plain \f1\i\lang1033\fs24  averit ... \plain \f1\lang1033\fs24  \emdash  \plain \f1\i\lang1033\fs24 ... blanda proferunt. Quod ut nos facere possimus, virginem benedictam adeamus etc. 
\line \plain \f1\lang1033\fs24  87r\endash 94v \plain \f1\i\lang1033\fs24  Et cum apparuisset sigillum quartum etc. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Karissimi, loquendo de premio infernali scire debetis, quod hoc verbum propositum per glosam sic exponitur, qui se ipsos pallidos formant}}\plain \f1\i\lang1033\fs24  ... \plain \f1\lang1033\fs24  \emdash  \plain \f1\i\lang1033\fs24 ... qui sibi filias dyaboli in hac vita desponsaverunt. Rogemus ergo dominum etc}

