\pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\lang1033\fs24  94v\endash 105v {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Sermones II }}
\par \pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\lang1033\fs24  94v\endash 95v \plain \f1\i\lang1033\fs24  Beati qui habitant in domo tua domine, Psalm. \plain \f1\lang1033\fs24  (83,5)\plain \f1\i\lang1033\fs24 . {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Karissimi, locuturi de beatitudine celestis patrie aliqualis timor invasit propter insufficienciam tam sciencie quam meritorum }}\plain \f1\i\lang1033\fs24 ... \plain \f1\lang1033\fs24  \emdash  \plain \f1\i\lang1033\fs24 ... quod nigredo humilitatis ministrare novit. Rogemus ergo beatam virginem Mariam etc. 
\line \plain \f1\lang1033\fs24  95v\endash 105v \plain \f1\i\lang1033\fs24  Beati qui habitant in domo tua domine, ubi supra. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Karissimi, sicut heri percepistis de hereditate dyaboli, quam eternaliter dare consuevit suis amicis, sic hodie}}\plain \f1\i\lang1033\fs24  ... \plain \f1\lang1033\fs24  \emdash  \plain \f1\i\lang1033\fs24 ... animam meam ad te currentem sursum attollat et quantum fas est eam tuo divino lumini (?) immergat; qui cum deo patre ... regnas per infinita secula seculorum. Amen. \plain \f1\lang1033\fs24  \emdash  Rest von 105v und 106 leer. }

