\par \pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\i\lang1033\fs24  Exiit edictum a Cesare Agusto (!) ut describeretur universus orbis \plain \f1\lang1033\fs24  (Lc 2,1)\plain \f1\i\lang1033\fs24 . {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 In duabus festivitatibus nativitatis scilicet et ephiphanie (!) VIII sumati[m] (!) possumus notare. Primum quod in eius nativitate mundus describitur}}\plain \f1\i\lang1033\fs24  ... \plain \f1\lang1033\fs24  \emdash  \plain \f1\i\lang1033\fs24 ... ducente nos domino nostro, qui cum p. et fi. et s. }

