\pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\lang1033\fs24  233vb\endash 234va {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Hugo de Sancto Victore}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Miscellanea (I 178) }}
\par \pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\i\lang1033\fs24  Medici qui morbos corporum curare solent quatuor qualitates ... \plain \f1\lang1033\fs24  \emdash  \plain \f1\i\lang1033\fs24 ... si ceciderint plus rei habentur etc. 
\par \pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\lang1033\fs20  PL 177, c.545sq. \emdash  Auch in Admont, 146, f.189 und 177, f.170\endash 184v; Eichst\u228 \'e4tt, cod. st 215, f.271v (siehe Initenregister, mit Lit.). Vgl. D. \plain \f1\scaps\lang1033\fs20 Van den Eynde\plain \f1\lang1033\fs20 , Le Liber Magistri Hugonis, in: Franciscan Studies 23 (1963) 268\endash 299. \plain \f1\scaps\lang1033\fs20 Rochais\plain \f1\lang1033\fs20 , Enqu\u234 \'eate sur les sermons ..., in: Analecta Sacri Ordinis Cisterciensis 18 (1962) 146 Anm.4. }

