\pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\lang1033\fs24  198r\endash 199r {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Bernardus Claraevallensis (Ps.)}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Planctus (rhythmicus)}}\plain \f1\b\lang1033\fs24   
\par \pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\i\lang1033\fs24  >Status religiosorum modernus< Olim nostrum ordinem principes amabant Et Romani presules ipsum honorabant Grata privilegia gratis nobis dabant Et preter suffragia nichil postulabant ... \plain \f1\lang1033\fs24  \emdash  Endet mit \plain \f1\i\lang1033\fs24  Signum est quod dominus non vult nos perire Qui nos tamquam filios non cessat ferire Ipse per hoc tristia det nobis hinc transire Quod ad vera gaudia possimus venire. >Amen< \plain \f1\lang1033\fs24  (17 Vierzeiler). 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20  Ausgabe: \plain \f1\scaps\lang1033\fs20 Wattenbach\plain \f1\lang1033\fs20 , Monumenta Lubensia, Breslau 1861, S.29. \emdash  \plain \f1\scaps\lang1033\fs20 Walther\plain \f1\lang1033\fs20 , Initia 13172. }

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

