\pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\lang1033\fs24  199r\endash 200v {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Tornamentum religiosorum (rhythmicum)}}\plain \f1\b\lang1033\fs24   
\par \pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\i\lang1033\fs24  >Torneamentum religiosorum< Cum in nocte video in choro conventum Et ad laudem domini iungitur intentum Esse me considero ut ad torneamentum Ubi non est licitum ire somnolentum. ... \plain \f1\lang1033\fs24  \emdash  \plain \f1\i\lang1033\fs24 ... Et partem cum ceteris meruit habere. 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs20 Walther\plain \f1\lang1033\fs20 , Initia, 3634}

