\pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\lang1033\fs24  265ra\endash 296vb {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Albertus Engelschalk}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Sermones dominicales (Pars II) }}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  265ra\endash vb \plain \f1\i\lang1033\fs24  >Ewangelium in die festo pasche< In illo tempore Maria Magdalena et Maria Iacobi et Salomee emerunt aromata ... Hoc ewangelium scribitur Marci XVI \plain \f1\lang1033\fs24  (1)\plain \f1\i\lang1033\fs24 . In quo postquam declaratum est in precedentibus quomodo Christus pro nobis miserabiliter et innocens occisus est ... \plain \f1\lang1033\fs24  A.E.95. 
\line 265vb\endash 266vb A.E.102, 266vb\endash 267vb A.E.105, 268ra A.E.108, 269ra A.E.111, 270ra A.E.114, 271ra A.E.118, 272ra A.E.123, 273ra A.E.130, 274ra A.E.133, 275ra A.E.136, 276ra A.E.139, 277ra A.E.142, 278ra A.E.145, 279ra A.E.148, 280ra A.E.151, 281ra A.E.154, 282ra A.E.157, 283ra A.E.160, 284ra A.E.163, 285ra A.E.166, 286ra A.E.169, 287ra A.E.172, 288ra A.E.175, 289ra A.E.178, 290ra A.E.181, 291ra A.E.185, 292ra A.E.188, 293ra A.E.191, 294ra A.E.194, 295ra A.E.197, 296ra A.E.200, 296va A.E.203 \emdash  \plain \f1\i\lang1033\fs24 ... idest cognoscere feci quod timeas dominum. \plain \f1\lang1033\fs24  \emdash  Einige Zeilen leer. \emdash  Predigten f\u252 \'fcllen meist genau ein Blatt; meist nur jede dritte der urspr\u252 \'fcnglichen Sammlung.}

