\pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\lang1033\fs24  168va\endash 169vb {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Tractatus de conferentibus et nocentibus}}\plain \f1\b\lang1033\fs24   
\par \pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\i\lang1033\fs24  Conferentibus cerebro in gravi eius oppressione ut epylencia appo\plain \f1\lang1033\fs24  [nuntur]\plain \f1\i\lang1033\fs24   suffocatione aer serenus, aloe, thymus \u8230 \'85 \plain \f1\lang1033\fs24  Abschnitt 2: \plain \f1\i\lang1033\fs24  Nocent cerebro argentum, vinum, cerusa ferri \u8230 \'85 \plain \f1\lang1033\fs24  \emdash  \plain \f1\i\lang1033\fs24  \u8230 \'85 pisces et carnes per salem indurati, omne quod est nimis ventosum. Explicit de conferentibus et nocentibus. \plain \f1\lang1033\fs24  \emdash  Rest der Seite leer. 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20  \u196 \'c4hnlicher Traktat (Explicit stimmt \u252 \'fcberein, Incipit \u228 \'e4hnlich) in Erfurt, WB, CA 2\u176 \'b0 289, f.47v\endash 48v}

