\pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\lang1033\fs24  88r\endash 93r {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Iacobus Publicius}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Suprascriptiones epistolarum}}\plain \f1\b\lang1033\fs24   
\par \pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\lang1033\fs24  Vorwort \plain \f1\i\lang1033\fs24  Nonnullos fore vereor qui honesto labori meo arrogancie nomen inscribere non dubitabunt ... \plain \f1\lang1033\fs24  Text \plain \f1\i\lang1033\fs24  Maiorum laudes prestantesque tituli ... \plain \f1\lang1033\fs24  \emdash  \plain \f1\i\lang1033\fs24 ... gratum et acceptum novitate saltem rei te habiturum spero. 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20  Gedruckt \plain \f1\scaps\lang1033\fs20 Hain\plain \f1\lang1033\fs20   13546, f5r\endash g3r (\plain \f1\i\lang1033\fs20  Panagericium Iacobi P. ad illustrissimum principem Tarantinum\plain \f1\lang1033\fs20 ). Vgl. \plain \f1\scaps\lang1033\fs20 Bertalot\plain \f1\lang1033\fs20 , Initia II 11561 ('Maiorum laudes...'). \plain \f1\scaps\lang1033\fs20 Bertalot\plain \f1\lang1033\fs20 , Studien, I 242 Anm.2. \plain \f1\scaps\lang1033\fs20 Sottili\plain \f1\lang1033\fs20   und \plain \f1\scaps\lang1033\fs20 Hilg\plain \f1\lang1033\fs20   zu Augsburg, UB, Oettingen-Wallerstein II. 1. 2\u176 \'b0 102, f.227r\endash 239r}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

