\pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\lang1033\fs24  174r\endash 183r {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Leonardus Aretinus}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Liber de militia}}\plain \f1\b\lang1033\fs24   
\par \pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\i\lang1033\fs24  >Leonardi Aretini de militia ad Rainaldum Albicum (!) equitem Florentinum liber incipit.< Fateor clarissime vir et michi ipsi iam sepe in dubium venisse hanc nostri temporis miliciam ... \plain \f1\lang1033\fs24  \emdash  \plain \f1\i\lang1033\fs24 ... aliquando faciamus. etc. 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs20 Bertalot\plain \f1\lang1033\fs20 , Initia, II 7480. Ed. C.C. \plain \f1\scaps\lang1033\fs20 Bayley\plain \f1\lang1033\fs20 , War and society in Renaissance Florence. The 'De militia' of Leonardo Bruni, Toronto 1961; siehe hierzu H.M. \plain \f1\scaps\lang1033\fs20 Goldbrunner\plain \f1\lang1033\fs20 , Leonardo Bruni De militia. Bemerkungen zur handschriftlichen \u220 \'dcberlieferung, in: Quellen und Forschungen aus italienischen Archiven 46, 1966, 478\endash 487.}

