\pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\lang1033\fs24  204r\endash 205v {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Nicolaus Perotti}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Epistola ad Iacobum Constantium Fanensem}}\plain \f1\b\lang1033\fs24   
\par \pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\i\lang1033\fs24  Decrevi post hac omnes non solum acciones ... \plain \f1\lang1033\fs24  \emdash  \plain \f1\i\lang1033\fs24 ... quod sencias ad me scribas Vale. \plain \f1\lang1033\fs24  \emdash  Rest von 205v leer. 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs20 Bertalot\plain \f1\lang1033\fs20 , Initia, II 4573. Auch im Vat. Reg. lat. 786, f.46v\endash 48v.}

