\uc1
\pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\lang1033\fs24  206v {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Petrus Paulus Vergerius}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Epistola ad Nicolaum de Leonardis physicum}}\plain \f1\b\lang1033\fs24   
\par \pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\i\lang1033\fs24  >Paulus Vergerius Leoni (?) physico salutem< Hodie apud dominum Franciscum cardinalem Florentinum ... libellum ... reperi ... de re uxoria ... \plain \f1\lang1033\fs24  \emdash  \plain \f1\i\lang1033\fs24 ... non possum non damnare. Vale. 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs20 Bertalot\plain \f1\lang1033\fs20 , Initia, II 8846 (zahlreiche Hss.)}

