\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  140vb\endash 141ra {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Exemplum de efficacia sanguinis}}\plain \f1\lang1033\fs24   Christi \plain \f1\i\lang1033\fs24  Nota exemplum satis pulchrum de efficacia sanguinis Christi, quod pro precedentibus materiis 5ta vel 6ta feria proponi ppotest. ... notat magister in historiis \plain \f1\lang1033\fs24  (Migne, PL 198, c.1353 \u252 \'fcber den Wurm Tamir Salomons)\plain \f1\i\lang1033\fs24  .... \plain \f1\lang1033\fs24  \emdash  \plain \f1\i\lang1033\fs24 ... sic deus pater viso sanguine filii sui etc}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

