\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  141rb\endash 142va {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Sermo in die sancto pascae}}\plain \f1\b\lang1033\fs24   
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24  
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 >In die sancto pasche< Ioseph filius accrescens et decorus aspectu ... habentes iacula, Gen. 49\u176 \'b0 \plain \f1\lang1033\fs24  (22)\plain \f1\i\lang1033\fs24 . Erecti de tumulis peccatorum, dilecti, quod ... \plain \f1\lang1033\fs24  \emdash  \plain \f1\i\lang1033\fs24 ... portate deum in corde et corpore vestro. Dic aliud exemplum scilicet de perseverancia et conclude: qui perseveraverit in finem, hic salvus erit. Quod et nobis fiat. Amen}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

