\par \pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\i\lang1033\fs24  Sanctificavi domum quam edificavi et posui nomen meum ibi usque in sempiternum, E. II\plain \f1\i\super\lang1033\fs24 a\plain \f1\i\lang1033\fs24   \plain \f1\lang1033\fs24  (III Reg. 9,3)\plain \f1\i\lang1033\fs24   Hec possunt intelligi dicta a Christo ... \plain \f1\lang1033\fs24  \emdash  \plain \f1\i\lang1033\fs24 ... Ite maledicti in ignem eternam. A quo vos custodiat pater et filius et spiritus sanctus. Amen. 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20  Auch in Klosterneuburg, Chorherrenstift, 441}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

