\pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\lang1033\fs24  217r\endash 222r {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Sermo de annuntiatione beatae Mariae virginis}}\plain \f1\b\lang1033\fs24   
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Sume tibi vas unum et mitte ibi manna quantum potest capere ganior (!) et repone coram domino ad servandum in cunctas generaciones vestras, Exo. XVII (16,33). Hec verba locutus est Moyses ad Aaron summum sacerdotem}}\plain \f1\i\lang1033\fs24  ... Hodie ... agimus diem venerabilem ... in qua ... virgo Maria ... effecta est mater dei ... \plain \f1\lang1033\fs24  \emdash  \plain \f1\i\lang1033\fs24 ... et penurie devotorum. Rogemus. \plain \f1\lang1033\fs24  \emdash  Vorn im Inhaltsverzeichnis als \plain \f1\i\lang1033\fs24  Sermo de annunciacione beate Marie virginis}

