\pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\lang1033\fs24  284v\endash 287r {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 De misericordia}}\plain \f1\b\lang1033\fs24   
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24  >De misericordia< Estote misericordes, Luc. 6 \plain \f1\lang1033\fs24  (36)\plain \f1\i\lang1033\fs24 . Inter omnes ceteras virtutes que deo et hominibus placent est misericordia, cum ipsa sit mater et nutrix pauperum et orphanorum ... \plain \f1\lang1033\fs24  \emdash  \plain \f1\i\lang1033\fs24 ... Exi a me quia homo}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

