\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  181ra\endash 182rb {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Notabilia chori Augustensis}}\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  >Notabilia chori Augustensis< Hec sunt notabilia chori Augustensis de officio misse. Et primo de gloria in excelso quod in omni die dominico canitur, scilicet ab adventu domini usque in nativitatem, set a septuagesima usque pasce non canitur ... \plain \f1\lang1033\fs24  Abschnitte folgen \plain \f1\i\lang1033\fs24  >De Credo, De prefatione, De galli cantu< \plain \f1\lang1033\fs24  und \plain \f1\i\lang1033\fs24  >De Ite missa est< \plain \f1\lang1033\fs24  \emdash  \plain \f1\i\lang1033\fs24 ... per totum annum missa cum Benedicamus domino concluditur. etc.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

