\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  305v {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Versus >Ad idem versus}}\plain \f1\i\lang1033\fs24  < Aspice peccator, si non sum verus amator Ut vivas morior, non est dileccio maior. \plain \f1\lang1033\fs24  \u196 \'c4hnlich, aber mehr Verse in Cgm 809, Nr. 30q (f.34r). Auch in Cgm 817, Nr.1. \plain \f1\scaps\lang1033\fs24 Walther\plain \f1\lang1033\fs24 , Initia 1588. \plain \f1\scaps\lang1033\fs24 H\plain \f1\scaps\lang1033\fs24 \u246 \'f6\plain \f1\scaps\lang1033\fs24 ver\plain \f1\lang1033\fs24 , Theologia mystica, S.17 Nr.14.}

