\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5260[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Braunes Leder auf Holzdeckeln}}\plain \f1\lang1033\fs20   ({\field{\*\fldinst HYPERLINK "hida://5060[0].5064/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 zeitgen\u246 \'f6ssisch}}\plain \f1\lang1033\fs20 ); {\field{\*\fldinst HYPERLINK "hida://5300[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Streicheisenlinien, Einzel- und Rollenstempel}}\plain \f1\lang1033\fs20   (floral). Spuren zweier Schlie\u223 \'dfen, einer Ketten\u246 \'f6se und von Beschl\u228 \'e4gen (mittig und an beiden Ecken). Auf dem R\u252 \'fccken mit Tinte Reiser-Nummer (\plain \f1\i\lang1033\fs20  p.52 n\u176 \'b0 22\plain \f1\lang1033\fs20 , darunter \plain \f1\i\lang1033\fs20  p.57 n.24\plain \f1\lang1033\fs20 ), unten auf Papierschild (gestrichen \plain \f1\i\lang1033\fs20  p.57 n.21\plain \f1\lang1033\fs20 , darunter Ehinger-Nummer \plain \f1\i\lang1033\fs20  179 24\plain \f1\lang1033\fs20   (!)}

