\pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\lang1033\fs24  17vb {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Prosa }}
\par \pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\i\lang1033\fs24  Homo natus ad laborem, per erumpnam et dolorem, in brevi consumitur 
\line Sicut umbra cum declinat ad occasum, sic festinat corpus cum dissolvitur. 
\line Res est vilis et inermis, carnem cuius edit vermis, postquam hamo regitur. 
\line Heu heu michi heu misero ubi ubi in die illa ero, quo wltu, quibus oculis apparebo, ubi pietas non erit in iudice iustus iudex equa lance sua recompensabit unicuique. deus misere angustie michi sunt undique, sed tu succurre parce ignosce, deus tu. 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20  'Homo natus ad laborem': AH 50, 528. AH 21, S.115\endash 116, 197. AH 20, 14. \plain \f1\scaps\lang1033\fs20 Werner\plain \f1\lang1033\fs20 , Beitr\u228 \'e4ge, Nr.330.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

