\uc1
\pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\lang1033\fs24  34r {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Sententiae in evangelium Lucam}}\plain \f1\b\lang1033\fs24   
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24  >In Lucam< Cum singulis evangelistis propria facies atribuitur (!), facies vituli Luce describitur ... \plain \f1\lang1033\fs24  \emdash  \plain \f1\i\lang1033\fs24 ... Sciendum est, quod totum novum testamentum grece scriptum est preter Matheum et epistolam Pauli ad Hebreos}

