\pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\lang1033\fs24  36r\endash 40v {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Rolandus Bandinelli (Alexander III)}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Sententiae de matrimonio}}\plain \f1\b\lang1033\fs24   
\par \pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\i\lang1033\fs24  >De matrimonio< Pertractatis aliis sacramentis superest ut de sacramento matrimonii disputemus, de quo primo queritur quid sit, secundo a quo sit institutum, tertio quando, quarto ubi, quinto quare, sexto que sint necessaria ad matrimonium contrahendum ... \plain \f1\lang1033\fs24  37v \plain \f1\i\lang1033\fs24  De gradibus consanguinitatis videndum est; unde primo queritur, quid sit gradus ... \plain \f1\lang1033\fs24  39r Schema ('Arbor consanguinitatis') \emdash  \plain \f1\i\lang1033\fs24 ... ut ergo hec contrarietas de medio tollatur, tali distinctione credimus fore utendum. 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20  Siehe \plain \f1\scaps\lang1033\fs20 Weigand\plain \f1\lang1033\fs20 , 1969 und 1980. Ferner \plain \f1\scaps\lang1033\fs20 Weigand\plain \f1\lang1033\fs20 , Fr\u252 \'fche Kanonisten und ihre Karriere in der Kirche, ZRG KA 107, 1990, 135\endash 155. \emdash  Zur 'Arbor' siehe \plain \f1\scaps\lang1033\fs20 Schadt\plain \f1\lang1033\fs20 , Arbores, Register S.398}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

