\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Donavit illi nomen quod super omne nomen, ut in nomine Ihesu omne genu flectatur celestium, terrestium et infernorum (Ad Phil. 2,9). Saint Pol li apostle dit}}\plain \f1\i\lang1033\fs24 , que deu pere celeste donat ... \plain \f1\lang1033\fs24  \emdash  Endet unvollst\u228 \'e4ndig 268vb mit dem Hinweis \plain \f1\i\lang1033\fs24  Verte duo folia retro. \plain \f1\lang1033\fs24  \emdash  268rb auf unterem Rand zwei nicht entzifferbare W\u246 \'f6rter.}

