\pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\lang1033\fs24  27v\endash 34r {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Sermo de Iohanne evangelista}}\plain \f1\b\lang1033\fs24   
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24  >Sermo de beato Iohanne ewangelista< Hic est discipulus ille quem diligebat Ihesus qui et recubuit in cena super pectus eius, Ioh. Ultimo \plain \f1\lang1033\fs24  (21, 24. 21)\plain \f1\i\lang1033\fs24 . {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Hic sunt tria scilicet quis magister, quis discipulus et quod beatus Iohannes plus est dilectus a domino}}\plain \f1\i\lang1033\fs24   \u8230 \'85 \plain \f1\lang1033\fs24  \emdash  \plain \f1\i\lang1033\fs24  \u8230 \'85 usque in perpetuum revelaret sicut per totum patet in Apokalipsi. }

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

