\pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\lang1033\fs24  34r\endash 39r {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Sermo de assumptione}}\plain \f1\b\lang1033\fs24   
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24  >Sequitur sermo de assumpcione< Veni de Libano, veni, coronaberis, Cant. 4 \plain \f1\lang1033\fs24  (Ct 4,8)\plain \f1\i\lang1033\fs24 . {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Rex celestis triplicem facit vocacionem, primo vocat ad eternum convivium}}\plain \f1\i\lang1033\fs24   \u8230 \'85 \plain \f1\lang1033\fs24  \emdash  \plain \f1\i\lang1033\fs24  \u8230 \'85 de torrente voluptatis tue potabis eos et illam excellencius}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\lang1033\fs24  39v\endash 59r {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Sermo de historia dominicae passionis}}\plain \f1\b\lang1033\fs24   
\par \pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\i\lang1033\fs24  >Sequitur historia dominice passionis< Humiliavit semetipsum factus obediens usque ad mortem, Phil. 4 \plain \f1\lang1033\fs24  (2,8)\plain \f1\i\lang1033\fs24 . {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Conswetudo est: mulier que habuit virum, quem intime dilexit, ipso mortuo solet omni anno facere anniversarium suum et sui recolere}}\plain \f1\i\lang1033\fs24   \u8230 \'85 \plain \f1\lang1033\fs24  \emdash  \plain \f1\i\lang1033\fs24  \u8230 \'85 quod quilibet crucem suam propriam debet portare quam diu potest contra dicentes solum Orate pro me. \plain \f1\lang1033\fs24  \emdash  Rest von 59r und 59v leer. 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20  Auch in Poitiers, BM, 247, f.260v; Uppsala, UB, C 16, f.304, und C 27, f. 267. }

