\pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\lang1033\fs24  248r\endash 253v {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Othlo Emmeramensis}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Vita sancti Wolfgangi confessoris}}\plain \f1\b\lang1033\fs24   
\par \pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\i\lang1033\fs24  Beatus igitur Wolfgangus nacione Swevigera ex ingeniis (!) parentibus nec ut sibi salutem (?) optat nec divicias nec paupertatem pacientibus ... \plain \f1\lang1033\fs24  \emdash  252v \plain \f1\i\lang1033\fs24 ... non nostris vicibus ascribamus. Hec ille. \plain \f1\lang1033\fs24  Weitere Abschnitte mit 'Hec ille' geschlossen bis 253v. 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20  MGH Scriptores IV S.525\endash 542. BHL 8990. Vgl. A. \plain \f1\scaps\lang1033\fs20 Lhotsky\plain \f1\lang1033\fs20 , Quellenkunde zur Mittelalterlichen Geschichte \u214 \'d6sterreichs, 1963, S.255. \emdash  Auch in Clm 28596, f.75r\endash 90r. Herzogenburg, 57, f.211r. Melk, 1869, f.289v. }

