\pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\lang1033\fs24  294v\endash 298r {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Sermo in die palmarum}}\plain \f1\b\lang1033\fs24   
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24  >In die palmarum< Ite in castellum quod contra vos est, Mt. 51 \plain \f1\lang1033\fs24  (Mt 21,2)\plain \f1\i\lang1033\fs24 . {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 In quibus verbis tria facit: primo inducit transgressionis motum}}\plain \f1\i\lang1033\fs24 , secundo attestacione loca, tercio predicit congressione actum. Primum igitur castellum est celeste paradisum ... \plain \f1\lang1033\fs24  \emdash  \plain \f1\i\lang1033\fs24 ... cum floribus clare contemplacionis et dileccionis. >Explicit sermo bonus complete< }

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

