\pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\lang1033\fs24  264v\endash 270v {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Nicolaus de Dinkelspuhel}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Sermo in visitatione monachorum }}
\par \pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\i\lang1033\fs24  >Sermo pro visitacione \plain \f1\lang1033\fs24  (\plain \f1\i\lang1033\fs24  magistri Nicolai de Dinckelspuchel \plain \f1\lang1033\fs24  eingef\u252 \'fcgt)\plain \f1\i\lang1033\fs24   monachorum ordinis sancti Benedicti et Augustini Canonicorum regularium in ducatu Austrie< Hora est iam nos de somno surgere (!), scribit apostolus ad Ro. 11 \plain \f1\lang1033\fs24  (13,11)\plain \f1\i\lang1033\fs24 , et allegat beatus pater Benedictus in principio regule \plain \f1\lang1033\fs24  (prol., 8)\plain \f1\i\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Quamvis sompnus proprie dictus secundum Aristotelem in De sompno et vigilia sit quedam privacio actuum senciendi}}\plain \f1\i\lang1033\fs24  ... \plain \f1\lang1033\fs24  \emdash  \plain \f1\i\lang1033\fs24 ... in certa exspectacione future glorie, quam nobis ... concedere dignetur ... Ihesus ... qui ... benedictus. Amen. etc. 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20  Wien, Schottenstift, 152 (227) (52.d.3), f.175\endash 180. Vgl. Hildesheim, Andr. 13, f.222r, u.a.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

