\par \pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\i\lang1033\fs24  >Sermo de partibus miserie et de partibus eterne beatitudinis< \plain \f1\lang1033\fs24  292r \plain \f1\i\lang1033\fs24  Tristicia vestra vertetur in gaudium, Ioh. 16\u176 \'b0 \plain \f1\lang1033\fs24  (20)\plain \f1\i\lang1033\fs24 . {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Quia vero intencio Christi fuit ad litteram in hoc verbo introducere miseriam istius mundi et beatitudinem paradisi}}\plain \f1\i\lang1033\fs24  ... \plain \f1\lang1033\fs24  \emdash  \plain \f1\i\lang1033\fs24 ... et ossa vestra ut herba germinabunt. Cuius felicitatis participes nos efficiat per crucis sui (!) misterium qui ... regnat. Amen. 
\par \pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\lang1033\fs20  Vgl. Frankfurt, StuUB, Ms. Praed. 93, f.118vb ('Tristitia vestra \emdash  [Io 16,20)]. Intentio Christi'). }

