\pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\lang1033\fs24  196v\endash 198r {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Vita et miracula beatae Elisabeth regis Ungariae filiae}}\plain \f1\b\lang1033\fs24   
\par \pard\fi0\li0\ql\ri0\sb105\sa105\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Elyzabeth illustris regis Ungarie filia genere nobilis, sed fide ac religione nobilior}}\plain \f1\i\lang1033\fs24  ... \plain \f1\lang1033\fs24  \emdash  197v \plain \f1\i\lang1033\fs24 ... ad celestes nupcias evocabit. Post paululum vero anno domini M\u176 \'b0 CC\u176 \'b0 XXXI\u176 \'b0 ad extremam horam veniens dormivit in pace. 
\line >Miraculum< Cum fama sanctitatis et bonitatis beatae Elyzabeth ubicumque volaret ... \plain \f1\lang1033\fs24  \emdash  198r \plain \f1\i\lang1033\fs24 ... a te separar\plain \f1\lang1033\fs24  [er]\plain \f1\i\lang1033\fs24   in eternum. Ecce promitto coram quod pro salute anime mee crucesignatus transmarinas partes aggrediar et ubi dominus iusserit moriar. etc. \plain \f1\lang1033\fs24  \emdash  Im Inhaltsverzeichnis f.232r \plain \f1\i\lang1033\fs24  De sancta Elyzabeth lectiones et miraculum 195. 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20  BHL 2506 (hier ohne Prolog). Miraculum: BHL 2511. \emdash  Auch in Graz, UB, 1235, f.304; L\u252 \'fcneburg, RatsB, Theol. fol. 37, f.217vb; K\u246 \'f6ln, StA, W* 300, f.180r.}

