\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  96vb {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Iohannes Baco}}\plain \f1\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Lectura super Matthaeum (excerptum)}}\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  >De proprietate religiosorum< Item notandum secundum magistrum Iohannem Bathone ordinis Carmelitarum in lectura sua super Matheum capitulo X\u176 \'b0, quomodo licet religiosis habere proprium ... \plain \f1\lang1033\fs24  \emdash  \plain \f1\i\lang1033\fs24 ... Hec habentur libro 3\u176 \'b0 de statu monachorum capitulo Monachi et capitulo Cum ad monasterium et capitulo Super quodam.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\lang1033\fs24  99ra\endash 139vb {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Nicolaus de Dinkelspuhel}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Sermones super oratione dominica}}\plain \f1\b\lang1033\fs24   
\par \pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\i\lang1033\fs24  Si quid pecieritis patrem in nomine meo dabit vobis, Ioh.16 \plain \f1\lang1033\fs24  (23)\plain \f1\i\lang1033\fs24 . Chrysostomus super illud Math. 7\u176 \'b0 Petite et dabitur vobis dicit ... \plain \f1\lang1033\fs24  \emdash  \plain \f1\i\lang1033\fs24 ... tandem mereatur videre deum deorum in Syon in celesti patria. Quo nos perducat qui cum patre et sancto spiritu vivit et regnat unus deus in secula benedictus. 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20  Siehe \plain \f1\scaps\lang1033\fs20 Madre\plain \f1\lang1033\fs20 , 177\endash 180. \plain \f1\scaps\lang1033\fs20 Schneyer\plain \f1\lang1033\fs20 , Initien: N.v.D. Nr.246\endash 247, 249\endash 257}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

