\pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\lang1033\fs24  350va\endash 351vb {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Gregorius Flogel}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Sermo de sancto Bartholomaeo (Bambergae 1447)}}\plain \f1\b\lang1033\fs24   
\par \pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\i\lang1033\fs24  >De sancto Bartholomeo< In quo omnis edificacio constructa crescit in templum sanctum in domino, Ad Ephes. II\u176 \'b0 \plain \f1\lang1033\fs24  (21)\plain \f1\i\lang1033\fs24   et in epistola de festo beati. Bartholomeus edificavit templum domino in se et in aliis ... \plain \f1\lang1033\fs24  \emdash  \plain \f1\i\lang1033\fs24 ... Psalmista: Letatus sum etc. Rogemus. Collatus Bamberge anno XLVII. 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20  Initium \u228 \'e4hnlich in Melk, 1770, f.75r, und Budapest, Magy. Nemzeti Muz., 98, f.163v}

