\pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\lang1033\fs24  352ra\endash va {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Sermo dominica ultima}}\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  >Dominica ultima< Ecce dies veniunt, Iere. XXIIII \plain \f1\lang1033\fs24  (5)\plain \f1\i\lang1033\fs24 . Dicit enim Bernhardus: Sicut deus finito tempore quod ab eterno extitit ... \plain \f1\lang1033\fs24  \emdash  \plain \f1\i\lang1033\fs24 ... que est ultima disposicio hospicii preparandi. Dic ut scis. \plain \f1\lang1033\fs24  Erg\u228 \'e4nzungen auf unterem Blattrand von 352r. \emdash  Stuttgart, WLB, HB I 228, f.106 (vgl. \plain \f1\scaps\lang1033\fs24 Fiala/Hauke\plain \f1\lang1033\fs24   1970). Bad Windsheim, StB, 40, f.1r. \emdash  Rest von 352v leer. }

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

