\pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\lang1033\fs24  368ra\endash 370rb {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Iacobus de Voragine}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Sermo}}\plain \f1\b\lang1033\fs24   
\par \pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\i\lang1033\fs24  Erat homo ex Phariseis Nicodemus nomine, Ioh. III \plain \f1\lang1033\fs24  (1)\plain \f1\i\lang1033\fs24 . Olim ab ecclesia festum trinitatis non fiebat ... \plain \f1\lang1033\fs24  \emdash  \plain \f1\i\lang1033\fs24 ... Querite et accipietis. Sequitur \plain \f1\lang1033\fs24  (Ioh. 3,3)\plain \f1\i\lang1033\fs24 : Amen amen dico vobis nisi quis renatus fuerit.. Nota. \plain \f1\lang1033\fs24  Im Inhaltsverzeichnis vorn als \plain \f1\i\lang1033\fs24  Sermo de sancta trinitate. \plain \f1\lang1033\fs24  \emdash  Rest von 370rb leer. 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20  Vgl. \plain \f1\scaps\lang1033\fs20 Schneyer\plain \f1\lang1033\fs20 , III 227 ('Festum de trinitate olim', Iacobus de Voragine). }

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\lang1033\fs24  390va\endash 392ra {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Sermo dominica 14}}\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  >Dominica 14a< Nota philosophus II\u176 \'b0 Thopicorum (!): Homines ut in pluribus sunt mali ut in paucioribus boni. Unde primo Rethorice dicit: Sicut optimum animalium est homo legem ferens sicut pessimum est homo a lege et iusticia recedens. \emdash  Cum ingrederetur Ihesus in quoddam castellum, Luc. XVII \plain \f1\lang1033\fs24  (12)\plain \f1\i\lang1033\fs24 . Sub tipo leprosorum mundatorum ostendit dominus in isto ewangelio tria, primo consciencie per peccatum feditatem ... \plain \f1\lang1033\fs24  \emdash  \plain \f1\i\lang1033\fs24 ... frequenta canticum. Rogemus ergo dominum Ihesum Christum etc. \plain \f1\lang1033\fs24  Im Inhaltsverzeichnis vorn aufgef\u252 \'fchrt. }

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

