\pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\lang1033\fs24  403r\endash 406r {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Gregorius Flogel (?)}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Sermo in die sancti Iohannis apostoli in principio sacerdotum}}\plain \f1\b\lang1033\fs24   
\par \pard\fi0\li0\ql\ri0\sb105\sa105\itap0 \plain \f1\i\lang1033\fs24  >Collecta (!) anno etc. XLVI in primiciis in die sancti Iohannis ewangeliste ad populares< Deinde dicit discipulo Ecce mater tua, Io. XVIIII \plain \f1\lang1033\fs24  (27)\plain \f1\i\lang1033\fs24 . Quamvis Ihesus Christus dominus noster Marie filius pendens pro salute tocius mundi in cruce ... \plain \f1\lang1033\fs24  405r \plain \f1\i\lang1033\fs24 ... Ecce quanta privilegia gracias et indulgencias dat sacerdotalis dignitas. Restat unum de sacramentis quod est ordo sacer. In quo plene constituti et ordinati sunt et preelecti dei ministri sacerdotes ... \plain \f1\lang1033\fs24  \emdash  \plain \f1\i\lang1033\fs24 ... in eterna patria fruamur. Verba sunt beati Bernhardi. Quod nobis prestare dignetur Marie filius qui vivit ... Amen. \plain \f1\lang1033\fs24  \emdash  Darunter, gerahmt: \plain \f1\i\lang1033\fs24  >Markopptinus< \plain \f1\lang1033\fs24  Von gleicher Hand daneben: \plain \f1\i\lang1033\fs24  Submitto me correccioni cuiuslibet sapientis. \plain \f1\lang1033\fs24  \emdash  Rest der Seite und 406v\endash 410v leer. }

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

